mapper.select:
SELECT mn.menu_id, mn.tenant_id, mn.module_id, m.module_nm, mn.parent_menu_id, pmn.menu_nm AS parent_menu_nm, mn.menu_code, mn.menu_nm, mn.menu_url, mn.icon_nm, mn.sort_order, mn.use_at, mn.created_at, mn.updated_at, (EXISTS (SELECT 1 FROM tb_menu c WHERE c.parent_menu_id = mn.menu_id)) AS has_children FROM tb_menu mn JOIN tb_module m ON m.module_id = mn.module_id LEFT JOIN tb_menu pmn ON pmn.menu_id = mn.parent_menu_id WHERE mn.tenant_id = #{tenantId}
AND mn.module_id = #{moduleId}
AND mn.use_at = #{useAt}
ORDER BY mn.module_id ASC, mn.sort_order ASC, mn.menu_id ASC

SELECT mn.menu_id AS "menuId", p.permission_code AS "permissionCode"
FROM tb_menu mn
JOIN tb_menu_permission mp ON mp.menu_id = mn.menu_id
JOIN tb_permission p ON p.permission_id = mp.permission_id AND p.use_at = 'Y'
WHERE mn.tenant_id = #{tenantId}

AND mn.module_id = #{moduleId}


AND mn.use_at = #{useAt}

ORDER BY p.sort_order ASC, p.permission_id ASC
